UPDATE results SET statement_tex = 'Let $c_0 \in \R$ and let $f \colon [1,\infty) \to \C$ be locally integrable with $f(x) = O_\varepsilon(x^{c_0+\varepsilon})$ for every $\varepsilon > 0$. The \emph{Mellin transform} of $f$ is the function
\[ (\mathcal M f)(s) = \int_1^\infty f(x)\, x^{-s-1}\, dx \qquad (\Re s > c_0), \]
where the integral \hyperref[8JS8]{converges absolutely}.', statement_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-24 11:30:00', updated_by = 'claude' WHERE id = 115;
