UPDATE results SET statement_tex = 'For a \hyperref[8JH4]{primitive character} $\chi$ let
\[ H_\chi = \mathcal M G_\chi \qquad (\Re s > 1) \]
be the \hyperref[8JS2]{Mellin transform} of the \hyperref[8JF7]{smoothed prime sum}, which \hyperref[8JS3]{exists for $\Re s > 1$}. For a primitive character $\psi$, with \hyperref[8JG8]{cyclic family} $\mathcal C_\psi$, weights $a_\chi$ and weighted sum $\mathcal G_\psi = \sum_{\chi \in \mathcal C_\psi} a_\chi \Re G_\chi$, let
\[ \Phi_\psi(s) = (\mathcal M \mathcal G_\psi)(s) = \int_1^\infty \mathcal G_\psi(x)\, x^{-s-1}\, dx \qquad (\Re s > 1). \]
For $\rho \in \C$ let $m_\chi(\rho) \ge 0$ be the multiplicity of $\rho$ as a zero of $L(s,\chi)$, with $m_\chi(\rho) = 0$ if $\rho$ is not a zero, and put
\[ S_\rho = \frac12 \sum_{\chi \in \mathcal C_\psi} a_\chi \bigl(m_\chi(\rho) + m_{\bar\chi}(\rho)\bigr). \]
Finally let
\[ Z = \left\{ \rho \in \C \;\middle|\; \Re\rho > 0,\ L(\rho, \chi) = 0 \text{ for some } \chi \in \mathcal C_\psi \right\}. \]', statement_html_cache = NULL, revision = revision + 1, updated_at = '2026-11-24 11:30:00', updated_by = 'claude' WHERE id = 117;
DELETE FROM refs WHERE source_result_id = 117 AND source_proof_id IS NULL;
\[ |f(x)\, x^{-s-1}| \le C_\varepsilon\, x^{c_0 + \varepsilon - \sigma - 1} \qquad (x \ge X). \]
The exponent is less than $-1$, so the right-hand side is integrable on $[X, \infty)$. On $[1, X]$ the function $f(x)\,x^{-s-1}$ is integrable because $f$ is locally integrable and $|x^{-s-1}| \le 1$ there.', NULL, 'ai_generated', 'claude', 'claude-opus-5-5', NULL, NULL, '2026-11-24 11:30:00', '2026-11-24 11:30:00', 'claude', 'claude');
