INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('result', '115', 2, 'definitions-no-reasoning-2026-11-24', '{"tag":"8JS2","type":"definition","title":"Mellin transform","statement_tex":"Let $c_0 \\in \\R$ and let $f \\colon [1,\\infty) \\to \\C$ be locally integrable with $f(x) = O_\\varepsilon(x^{c_0+\\varepsilon})$ for every $\\varepsilon > 0$. The \\emph{Mellin transform} of $f$ is the function\n\\[ (\\mathcal M f)(s) = \\int_1^\\infty f(x)\\, x^{-s-1}\\, dx \\qquad (\\Re s > c_0), \\]\nwhere the integral \\hyperref[8JS8]{converges absolutely}.","section_id":104,"position":1,"listed":1,"aliases":["mellin-transform"]}', 'claude');
