INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('result', '117', 2, 'definitions-no-reasoning-2026-11-24', '{"tag":"8JS4","type":"definition","title":"The transforms $H_\\chi$, $\\Phi_\\psi$ and the zero set $Z$","statement_tex":"For a \\hyperref[8JH4]{primitive character} $\\chi$ let\n\\[ H_\\chi = \\mathcal M G_\\chi \\qquad (\\Re s > 1) \\]\nbe the \\hyperref[8JS2]{Mellin transform} of the \\hyperref[8JF7]{smoothed prime sum}, which \\hyperref[8JS3]{exists for $\\Re s > 1$}. For a primitive character $\\psi$, with \\hyperref[8JG8]{cyclic family} $\\mathcal C_\\psi$, weights $a_\\chi$ and weighted sum $\\mathcal G_\\psi = \\sum_{\\chi \\in \\mathcal C_\\psi} a_\\chi \\Re G_\\chi$, let\n\\[ \\Phi_\\psi(s) = (\\mathcal M \\mathcal G_\\psi)(s) = \\int_1^\\infty \\mathcal G_\\psi(x)\\, x^{-s-1}\\, dx \\qquad (\\Re s > 1). \\]\nFor $\\rho \\in \\C$ let $m_\\chi(\\rho) \\ge 0$ be the multiplicity of $\\rho$ as a zero of $L(s,\\chi)$, with $m_\\chi(\\rho) = 0$ if $\\rho$ is not a zero, and put\n\\[ S_\\rho = \\frac12 \\sum_{\\chi \\in \\mathcal C_\\psi} a_\\chi \\bigl(m_\\chi(\\rho) + m_{\\bar\\chi}(\\rho)\\bigr). \\]\nFinally let\n\\[ Z = \\left\\{ \\rho \\in \\C \\;\\middle|\\; \\Re\\rho > 0,\\ L(\\rho, \\chi) = 0 \\text{ for some } \\chi \\in \\mathcal C_\\psi \\right\\}. \\]","section_id":104,"position":3,"listed":1,"aliases":["family-zero-set"]}', 'claude');
