INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('proof', '108', 1, 'definitions-no-reasoning-2026-11-24', '{"result_id":121,"body_tex":"Let $\\sigma = \\Re s > c_0$ and fix $\\varepsilon$ with $0 < \\varepsilon < \\sigma - c_0$. There are $C_\\varepsilon$ and $X \\ge 1$ with $|f(x)| \\le C_\\varepsilon x^{c_0+\\varepsilon}$ for $x \\ge X$, hence\n\\[ |f(x)\\, x^{-s-1}| \\le C_\\varepsilon\\, x^{c_0 + \\varepsilon - \\sigma - 1} \\qquad (x \\ge X). \\]\nThe exponent is less than $-1$, so the right-hand side is integrable on $[X, \\infty)$. On $[1, X]$ the function $f(x)\\,x^{-s-1}$ is integrable because $f$ is locally integrable and $|x^{-s-1}| \\le 1$ there.","status":"ai_generated","generated_by":"claude","generator_detail":"claude-opus-5-5","reviewed_by":null,"review_notes":null,"position":1}', 'claude');
